/**
 * The telemetry disclosure a person sees before sending can start: the interactive CLI prompt prints
 * these points, and the Windows installer dialog (`desktop/src-tauri/wix/telemetry-choice.wxs`,
 * generated by `desktop/scripts/telemetry-installer-dialog.ts`) shows the same text with a link to
 * the full policy. Import-free so the installer generator can read it without loading the CLI.
 */

/** The published privacy policy, linked from the installer dialog and the code signing policy. */
export const TELEMETRY_POLICY_URL = "https://opencodex.me/reference/code-signing/#privacy";

export const TELEMETRY_DISCLOSURE_HEADING = "Anonymous daily usage telemetry:";

export const TELEMETRY_DISCLOSURE_POINTS: readonly string[] = Object.freeze([
  "Sent daily to telemetry.opencodex.me: a daily-changing install hash, version, release channel, OS/arch, install channel, first-report flag, provider kind, model family, active minutes, request/token/error counts.",
  "Never sent: prompts, model outputs, request/response bodies, API keys, OAuth tokens, account IDs or emails, custom base URLs, hostnames, file paths, or error text.",
  "Public aggregates: project-wide totals are published at opencodex.me/dashboard.",
  "See the exact payload: ocx telemetry status --json",
  "Turn off anytime: ocx telemetry disable, the Proxy details toggle in the dashboard, or OCX_TELEMETRY=0 / DO_NOT_TRACK=1 in the proxy's own environment (a service does not see variables set in your shell).",
]);
